E = {}
def n(name, story, similar=(), note=None):
    E[name] = {"story": story, **({"storyNote": note} if note else {}), "similar": list(similar)}

n("עזמי", "עזמי בא מהמילה הערבית עזם, נחישות ותקיפות של רצון, והסיומת ־י הופכת אותה לתואר, כמו בעברית. השורש הערבי ע־ז־ם עניינו החלטה חזקה ועמידה בה גם כשקשה. מאותו שורש באה גם המילה הערבית עזימה, החלטה נחושה.")
n("פורת", "פורת בא מהשורש פ־ר־ה, שממנו באות גם המילים פרי, פוריות ופורה. בתנ״ך המילה מופיעה בברכה של יעקב ליוסף, שבה יוסף מתואר כבן פורת, כמו עץ פרי שגדל ליד מעיין. בעברית של היום שדה פורה הוא שדה שנותן יבול רב.")
n("צילה", "צילה בנויה על המילה צל, ופירושה מי שנותנת צל, מחסה מפני השמש. בארץ חמה צל הוא מקום של מנוחה, ובעברית המקראית המילה משמשת גם בהשאלה להגנה ולמחסה. בתנ״ך צילה היא אחת משתי נשותיו של למך, לצד עדה.")
n("צירל", None, note="Yiddish name; the card gives no meaning and its origin (Yiddish tsir 'ornament', or a form of Sarah) is not agreed.")
n("קירה", "קירה הוא שם שמוכר בשפות רבות, ולכל שפה יש לו מקור משלה. ברוסית ובשפות סלאביות נוספות הוא צורה לבנות של קיריל, שבא מהמילה היוונית קיריוס, אדון. השם נכתב ונהגה כמעט באותה צורה בשפות רבות של אירופה.")
n("ראיין", "ראיין הוא כתיב אחר של ריאן ורייאן, שם ערבי שבא מהשורש ר־ו־י, שעניינו שתייה ורוויה. פירושו מי שרווה, וגם מקום שופע מים וצמחייה. באנגלית ראיין הוא גם שם ממקור אירי, שנכתב באותיות עבריות באותה צורה, אבל אין לו קשר לשם הערבי.", ["ריאן", "רייאן"])
n("רביע", "רביע היא המילה הערבית לאביב, עונת הפריחה שבין החורף לקיץ. על שמה נקראים בלוח השנה המוסלמי שני חודשים, רביע אלאוול ורביע אלת'אני, כלומר האביב הראשון והאביב השני. השורש הערבי ר־ב־ע קשור גם למספר ארבע, כמו בעברית.")
n("רדואן", "רדואן היא מילה ערבית לרצון טוב ולשביעות רצון, להסכמה ולחסד שמישהו נותן. השורש הערבי שלה קרוב לשורש העברי ר־צ־ה, של המילים רצון ורצוי. במסורת המוסלמית רדואן הוא גם שמו של המלאך ששומר על שערי גן העדן.")
n("ריחאנה", "ריחאנה היא המילה הערבית לבזיליקום, צמח תבלין עם עלים ירוקים וריח חזק ונעים. היא באה מהשורש הערבי ר־ו־ח, והוא קרוב לשורש העברי של המילים ריח ורוח. ריחאן היא צורה של אותו שם, ובערבית המילה מתארת גם צמחים ריחניים בכלל.", ["ריחאן"])
n("רייזי", "רייזי היא צורת חיבה של רייזל, שם יידי שבא מהמילה רויז, ורד. הסיומת ־י מוסיפה לשם נימה של קרבה, כמו בצורות חיבה רבות ביידיש ובעברית. ריזל הוא כתיב אחר של רייזל, ובעברית הפירוש של כולם קרוב לשם ורד.", ["רייזל", "ריזל"])
n("שרי", "שרי היא צורה עתיקה של שרה, ויש שמפרשים אותה כשרה שלי, או הנסיכה שלי. בתנ״ך זה שמה הראשון של אשת אברהם, עד ששמה שונה לשרה, ובאותו מקום גם שמו של אברם שונה לאברהם. שתי הצורות באות מהשורש ש־ר־ר, של המילים שר ושררה, שעניינו שלטון והנהגה.", ["שרה"])
n("תאג'", "תאג' היא המילה הערבית לכתר, העטרה שעל ראשו של מלך. המילה הגיעה לערבית מהפרסית העתיקה, ובערבית היא משמשת גם בהשאלה לדבר היפה והחשוב בקבוצה. מאותה מילה בא גם שמו של מבנה מפורסם בהודו, טאג' מהאל.")
n("אבשלום", "אבשלום מחבר את המילים אבי ושלום, ופירושו אבי הוא שלום. שלום בעברית המקראית הוא גם שלמות וביטחון, ולא רק היעדר מלחמה. בתנ״ך אבשלום הוא בנו של דוד המלך, שמרד באביו ונהרג ביער אפרים.")
n("אבתיסאם", "אבתיסאם היא המילה הערבית לחיוך, לחיוך רך ושקט ולא לצחוק. היא באה מהשורש הערבי ב־ס־ם, וממנו נבנו גם באסם ובאסמה, מי שמחייך. בערבית של היום המילה משמשת גם לתיאור של פנים מאירות ונעימות.")
n("אחלאם", "אחלאם היא צורת הרבים של המילה הערבית לחלום. היא באה מהשורש הערבי ח־ל־ם, אותו שורש של המילים העבריות חלום וחולם. בערבית המילה מתארת גם תקוות ושאיפות לעתיד, כמו המילה חלום בעברית.")
n("אילף", "אילף היא מילה ערבית לקרבה, לחיבה ולהרגל של חברות קבועה. היא באה מהשורש הערבי א־ל־ף, שעניינו התרגלות והתקרבות, וממנו באה גם המילה הערבית אליף, חיה מבויתת. השורש קרוב לשורש העברי א־ל־ף, של הפועל לאלף, להרגיל ולאמן.")
n("אלהאם", "אלהאם היא המילה הערבית להשראה, לרעיון או לתחושה שמגיעים פתאום ומעוררים לפעולה. היא באה מהשורש הערבי ל־ה־ם, ובערבית של היום היא משמשת בעיקר בהקשר של יצירה, של שירה ושל אמנות.")
n("אליאם", "אליאם מחבר את המילים אלי ועם, ופירושו אלוהים הוא העם שלי. עם היא מילה עתיקה לקבוצה של אנשים שקשורים זה לזה, ובעברית המקראית גם לקרובי משפחה. בכתיב השם נכתבת האות א במקום האות ע, והצליל נשאר כמעט אותו צליל.")
n("אמאני", "אמאני היא צורת הרבים של המילה הערבית אמניה, משאלה, ופירושה משאלות ותקוות. היא באה מהשורש הערבי מ־נ־י, שעניינו רצון ומשאלה. בערבית של היום המילה מופיעה הרבה בברכות, באיחול שהמשאלות יתגשמו.")
n("אריג'", "אריג' היא מילה ערבית לניחוח, לריח טוב ומתוק שמתפשט באוויר, כמו של פרחים או של בושם. היא באה מהשורש הערבי א־ר־ג׳, ומשמשת בעיקר בשפה של שירה ושל תיאור. בערבית המילה מתארת ריח שנשאר באוויר גם אחרי שמקורו כבר הלך.")
n("בתאל", "בתאל מחבר את המילים בת ואל, ופירושו בתו של אלוהים. בת אל הוא כתיב אחר של אותו שם, בשתי מילים. באותה דרך נבנה גם השם בתיה, בתו של ה׳, ובו החלק השני הוא כינוי אחר לאלוהים.", ["בת אל"])
n("ג'ומעה", "ג'ומעה היא המילה הערבית ליום שישי, היום שבו מתאספים לתפילה המשותפת במסגד. היא באה מהשורש הערבי ג׳־מ־ע, שעניינו איסוף והתכנסות, וממנו באה גם המילה ג'אמע, מסגד גדול שמתכנסים בו.")
n("דהב", "דהב היא המילה הערבית לזהב, המתכת הצהובה והנוצצת. המילה הערבית והמילה העברית קרובות, וההבדל ביניהן הוא בעיקר באות הראשונה, כמו במילים נוספות שבהן ז בעברית היא ד בערבית. בסיני יש גם עיירת חוף בשם דהב, על שפת מפרץ אילת.")
n("דוראל", "דוראל מחבר את המילים דור ואל, ופירושו הדור של אלוהים. דור היא מילה עתיקה לכל האנשים שחיים באותה תקופה, וגם לזמן של חיי אדם אחד. דור ודורי נבנו על אותה מילה, בלי החלק אל.", ["דור", "דורי"])
n("דותן", "דותן הוא שמו של עמק ושל עיר עתיקה בצפון השומרון, ליד הדרך שעברה בין הגלעד למצרים. בתנ״ך האחים של יוסף רועים את הצאן בדותן, ושם הם מוכרים אותו לשיירה שיורדת למצרים. בעברית של היום עמק דותן הוא אזור חקלאי.")
n("הלן", "הלן הוא הצורה הצרפתית והאנגלית של השם היווני הלנה. מקובל לקשר אותו למילה היוונית הלה, לפיד או אור, אבל המקור אינו ודאי. הלני והילני הן צורות אחרות של אותו שם, בכתיב שקרוב יותר ליוונית.", ["הלני", "הילני"])
n("והיב", "והיב היא מילה ערבית לנדיב, למי שנותן מתנות ביד רחבה. היא באה מהשורש הערבי ו־ה־ב, שעניינו מתנה ונתינה, וממנו באה גם המילה הערבית הבה, מתנה. בערבית אלוהאב, הנותן, הוא גם אחד מכינויי האל.")
n("זוהיר", "זוהיר בא מהמילה הערבית זהר, פרחים, והוא צורה של הקטנה שפירושה פרח קטן. השורש הערבי ז־ה־ר עניינו גם זוהר ובהירות, כמו של פרח שבולט בצבעיו. מאותו שורש נבנה גם השם הערבי זוהרה.")
n("חני", "חני היא צורת חיבה של חנה, עם הסיומת ־י, שמוסיפה לשם נימה של קרבה. חנה בא מהשורש ח־נ־ן, שממנו באות גם המילים חן, חנינה ותחינה. באותה דרך נבנו צורות חיבה נוספות, כמו רחלי מרחל.", ["חנה"])
n("חסאן", "חסאן היא מילה ערבית לנאה ולטוב, למי שיפה במראה ובמעשים. היא באה מהשורש הערבי ח־ס־ן, שעניינו יופי וטוב, וממנו נבנו גם חסן ואיחסאן. בערבית של היום חסן היא גם המילה הרגילה לטוב ולנאה.")
n("טבע", "טבע היא המילה העברית לכל מה שלא נעשה בידי אדם: הצמחים, בעלי החיים, הנוף והשמיים. מאותו שורש באות גם המילים טבעי וטבעת, והמשמעות הקדומה שלו קשורה לטביעה של חותם. השם ניתן לבנים ולבנות.")
n("יהלום", "יהלום הוא אבן יקרה, שקופה ונוצצת, וקשה מאוד. בתנ״ך היהלום הוא אחת משתים עשרה האבנים שעל חושן הכוהן הגדול, ועל כל אבן נחקק שם של שבט. יש שקושרים את המילה לשורש ה־ל־ם, להכות, כי היהלום חזק מאבנים אחרות. השם ניתן לבנים ולבנות.")
n("מירב", "מירב הוא שם מקראי, ויש שמפרשים אותו כריבוי, מהשורש ר־ב־ב, של המילים רב ומרובה. בתנ״ך מירב היא הבת הבכורה של שאול המלך, ואחותה הצעירה היא מיכל. בעברית של היום המילה מרב פירושה הכמות הגדולה שאפשר.")
n("מליסה", "מליסה היא המילה היוונית לדבורה, והיא קרובה למילה היוונית לדבש. בשפות של אירופה מליסה היא גם שמו של צמח ריחני ממשפחת הנענע, שהדבורים נמשכות אל הפרחים שלו. בעברית דבורה הוא שם בעל אותו פירוש.")
n("נאיל", "נאיל היא מילה ערבית למי שמשיג ומקבל, למי שזוכה במה שביקש. היא באה מהשורש הערבי נ־י־ל, שעניינו השגה וזכייה, ובערבית של היום הפועל מאותו שורש משמש לזכייה בפרס או בתואר. נאילה היא הצורה לבנות של אותו שם.", ["נאילה"])
n("נהר", "נהר הוא זרם גדול של מים מתוקים שזורם בערוץ קבוע אל הים או אל אגם. בתנ״ך נהר יוצא מעדן להשקות את הגן, ומשם הוא נפרד לארבעה נהרות. בארץ הנהר המוכר הוא הירדן. מהמילה נהר נבנה גם השם נהרי, והשם ניתן לבנים ולבנות.", ["נהרי"])
n("נס", "נס הוא דבר פלא, אירוע שאיש לא ציפה לו. בעברית המקראית נס הוא גם דגל או תורן גבוה שמרימים כדי שיראו אותו מרחוק, ומכאן הביטוי להעלות על נס, לשבח ולהציג לפני כולם. מהמילה נס נבנה גם השם נסיה.", ["נסיה"])
n("סאבר", "סאבר היא מילה ערבית לסבלני, למי שיודע לחכות ולשאת קושי בלי להתלונן. היא באה מהשורש הערבי צ־ב־ר, שעניינו סבלנות, ומאותו שורש באה המילה הערבית לצמח הקוצני שבעברית נקרא צבר. סברי הוא שם נוסף שנבנה על אותו שורש.")
n("עוזיאל", "עוזיאל מחבר את המילים עוזי ואל, ופירושו אלוהים הוא העוז שלי. עוז היא מילה לכוח ולחוזק, ומאותו שורש באות גם המילים עז ועיזוז. בתנ״ך עוזיאל הוא אחד מבני קהת משבט לוי, דודם של משה ואהרן. עוז ועז הם שמות קצרים שנבנו על אותה מילה.", ["עוז", "עז"])
n("עיטם", "עיטם הוא שמו של עוף דורס גדול, בעל כנפיים רחבות, שחי ליד ים ונהרות וניזון בעיקר מדגים. המילה בנויה על העיט, השם העברי לעופות דורסים גדולים. העיטם בונה קן גדול על עצים גבוהים או על צוקים, וחוזר אליו שנה אחרי שנה.")
n("עמיעד", "עמיעד מחבר את המילים עמי ועד, ופירושו העם שלי לעד, לתמיד. עד היא מילה עתיקה לזמן שאין לו סוף, כמו בצירוף לעולם ועד. באותה דרך נבנה גם השם אליעד, שבו החלק הראשון הוא כינוי לאלוהים.")
n("ערבה", "ערבה היא עץ שגדל לאורך נחלים ובמקומות לחים, עם ענפים דקים ועלים ארוכים וצרים. בחג הסוכות הערבה היא אחד מארבעת המינים, לצד הלולב, האתרוג וההדס. בעברית ערבה היא גם מישור צחיח, ומכאן שמה של הערבה שבדרום הארץ, בין ים המלח לאילת.")
n("קורל", "קורל היא המילה האנגלית לאלמוג, בעל חיים ימי קטן שבונה שלד גיר ויוצר שוניות צבעוניות. המילה הגיעה לאנגלית מהיוונית דרך הלטינית. בארץ יש שוניות אלמוגים בים סוף, ליד חופי אילת.")
n("קרן", "קרן היא קרן אור, פס של אור שיוצא מהשמש או ממקור אחר. בתנ״ך הפועל קרן מתאר את פניו של משה כשירד מהר סיני, שהיו מוארות. בעברית קרן היא גם הקרן של בעל חיים, ומהמילה נבנו גם קרני וקורן.", ["קרני", "קורן"])
n("ראיה", "ראיה בנויה על השורש ר־א־ה, של המילים ראייה, מראה ומבט. בעברית של היום המילה ראיה, בניקוד אחר, היא גם הוכחה, דבר שמראה שמשהו נכון. מאותו שורש נבנה גם השם רואי, שפירושו הרואה אותי.")
n("רשיד", "רשיד היא מילה ערבית לנבון, למי שהולך בדרך הנכונה ומקבל החלטות בשיקול דעת. היא באה מהשורש הערבי ר־ש־ד, שעניינו הדרכה ובגרות, וממנו באה גם המילה הערבית מרשד, מדריך. בערבית של היום רשיד הוא גם מבוגר שיכול לנהל את ענייניו בעצמו.")
n("שבע", "שבע הוא צורה קצרה של בת שבע ושל בתשבע, שני כתיבים של אותו שם. יש שמקשרים את המילה שבע לשבועה, ויש שמקשרים אותה למספר שבע. גם בשם אלישבע החלק השני הוא אותה מילה.", ["בת שבע", "בתשבע"])
n("שילו", "שילו הוא כתיב של שילה, שמה של עיר עתיקה בהרי אפרים, שבה עמד המשכן בתקופה שלפני המלוכה. בתנ״ך המילה שילה מופיעה גם בברכה של יעקב ליהודה, במשפט שפירושו אינו ודאי. במקום העתיק נמצאו שרידים של העיר, והוא נקרא היום תל שילה.", ["שילה"])
n("שלהבת", "שלהבת היא להבה, לשון של אש שעולה ומתנועעת. המילה בנויה על השורש ל־ה־ב, של המילים להבה ולהבות, עם האות ש בתחילתה. בתנ״ך היא מופיעה בשיר השירים בצורה שלהבתיה, בתיאור של אהבה חזקה כמו אש. בעברית של היום שלהבת מתארת גם התלהבות ורגש חזק.")
n("שלם", "שלם היא מילה למה שאין בו חסר, שכל חלקיו נמצאים במקומם. היא באה מהשורש ש־ל־ם, שממנו באות גם המילים שלום, שלמות ותשלום. בתנ״ך שלם הוא שמה הקדום של ירושלים, העיר שמלכי צדק היה מלך שלה.")
n("שניר", "שניר הוא אחד השמות הקדומים של הר החרמון, ההר הגבוה שבצפון הארץ, שבחורף מכוסה לעיתים בשלג. בתנ״ך מסופר שכך קראו להר האמורים, ושהצידונים קראו לו שריון. מקור המילה שניר אינו ודאי.")
n("תלמה", "תלמה בנויה על המילה תלם, החריץ הארוך שהמחרשה פותחת באדמה כדי לזרוע בה. בשדה חרוש התלמים עוברים בשורות ישרות, זה לצד זה. בעברית של היום הביטוי ללכת בתלם פירושו לנהוג לפי הדרך המקובלת. תלם הוא שם נוסף שנבנה על אותה מילה.", ["תלם"])
n("תרצה", "תרצה בנויה על השורש ר־צ־ה, ופירושה היא תרצה, תאהב ותקבל ברצון. בתנ״ך תרצה היא אחת מחמש בנות צלפחד, וגם שמה של עיר עתיקה בשומרון, שהייתה בירת ממלכת ישראל לפני העיר שומרון. בשיר השירים היופי של האהובה מושווה ליופייה של תרצה.")
n("איחסאן", "איחסאן היא מילה ערבית לעשיית טוב, לנדיבות ולמעשה חסד כלפי אחרים. היא באה מהשורש הערבי ח־ס־ן, שעניינו יופי וטוב, וממנו נבנו גם חסאן וחסן. בערבית המילה מתארת גם עבודה שנעשית בשלמות ובמסירות.")
n("אליזבט", "אליזבט היא הצורה האירופית של השם העברי אלישבע, שעבר ליוונית וללטינית ומשם לשפות רבות. פירוש השם אלישבע הוא אלוהיי הוא שבועה, או אלוהיי נשבע. אליסה היא צורה קצרה של אליזבט, ובכל שפה של אירופה נבנו לו צורות קצרות וצורות חיבה משלו.", ["אלישבע", "אליסה"])
n("אמינה", "אמינה היא מילה לנאמנה ולמי שאפשר לסמוך עליה, בעברית ובערבית. היא באה מהשורש א־מ־ן, שממנו באות גם המילים אמונה, אמת ונאמן. בעברית של היום אמין הוא גם תיאור של מקור מידע או של מכשיר שאפשר לסמוך עליו.", ["אמין"])
n("אמליה", "אמליה הוא שם אירופי שמקורו במילה מהגרמנית העתיקה שפירושה עבודה ומאמץ, ומכאן הפירוש חרוצה. השם היה מוכר בגרמניה ובאיטליה, ומשם עבר לשפות נוספות. אמלי היא הצורה הצרפתית של אותו שם.", ["אמלי"])
n("אמן", "אמן היא מילה עתיקה שאומרים בסוף ברכה או תפילה, ופירושה כך יהיה, אני מסכים. היא באה מהשורש א־מ־ן, של המילים אמונה, אמת ונאמן. המילה עברה מהעברית לשפות רבות, והיא נאמרת כמעט באותו צליל בכל אחת מהן.")
n("אסתי", "אסתי היא צורת חיבה של השם אסתר. הסיומת ־י מוסיפה לשם נימה של קרבה, כמו בצורות חיבה נוספות, למשל חני מחנה ורחלי מרחל. מקובל לקשר את אסתר למילה הפרסית לכוכב.", ["אסתר"])
n("באסמה", "באסמה היא הצורה לבנות של באסם, מהמילה הערבית למחייך, למי שמחייכת. היא באה מהשורש הערבי ב־ס־ם, שממנו באה גם המילה אבתיסאם, חיוך. בערבית החיוך שהמילה מתארת הוא חיוך רך ושקט, ולא צחוק רם.", ["באסם"])
n("בהאא", "בהאא היא מילה ערבית לזוהר, ליופי ולהדר, לאור שיש למי שנראה טוב ומאיר. היא באה מהשורש הערבי ב־ה־י, שעניינו בהירות ויופי. בערבית המילה משמשת גם לתיאור של מקום מפואר ומלא הדר.")
n("בשיר", "בשיר היא מילה ערבית למבשר, למי שמביא בשורה טובה. היא באה מהשורש הערבי ב־ש־ר, אותו שורש של המילים העבריות בשורה, מבשר ולבשר. בשתי השפות השורש קשור להודעה על דבר משמח.")
n("בת ציון", "בת ציון מחבר את המילה בת עם ציון, אחד השמות הקדומים של ירושלים. בתנ״ך הנביאים משתמשים בצירוף פעמים רבות כדי לפנות אל העיר ואל תושביה, כמו אל אישה. בשירה העברית של הדורות הבאים הצירוף נשאר כינוי לירושלים ולעם ישראל.")
n("בתשבע", "בתשבע הוא כתיב של בת שבע במילה אחת. יש שקושרים את המילה שבע לשבועה, ולכן פירושו בת השבועה. בתנ״ך בת שבע היא אשתו של דוד המלך ואמו של שלמה, ושבע הוא צורה קצרה של השם.", ["בת שבע", "שבע"])
n("ג'וזף", "ג'וזף הוא הצורה האנגלית של השם העברי יוסף, שעבר ליוונית וללטינית ומשם לשפות רבות. יוסף בנוי על השורש י־ס־ף, ופירושו הוא יוסיף, ייתן עוד. בכל שפה של אירופה השם נהגה אחרת, כמו חוזה בשפה הספרדית וג'וזפה באיטלקית.", ["יוסף"])

